#!/bin/bash
# ASI-Bench file-exchange agent: mini-swe-agent (text-based bash actions) in the task workspace.
# Invoked by `asibench run --agent-cmd 'bash scripts/asi_agent.sh {workspace} MODEL API SEED TRAJ_DIR BASE'`
# (arguments, not env vars: asibench sanitizes the agent environment).
# Same harness and text format as the SWE-Pro eval; identical settings for every model.
set -u
W=$1 ASI_MODEL=$2 ASI_API=$3 ASI_SEED=$4 ASI_TRAJ_DIR=$5 BASE=$6
MINI=$BASE/venvs/harbor/bin/mini
# eval config generated by scripts/run_asi.sh (official mini_textbased.yaml, `bash` fence, sampling)
CFG=$BASE/asi-runs/$ASI_MODEL/mini_config.yaml
ID=$(basename "$(dirname "$W")")
mkdir -p "$ASI_TRAJ_DIR"
cd "$W" || exit 1
export HOSTED_VLLM_API_KEY=EMPTY MSWEA_COST_TRACKING=ignore_errors MSWEA_CONFIGURED=true MSWEA_GLOBAL_CONFIG_DIR=$BASE/mswea-config
exec "$MINI" -m "hosted_vllm/$ASI_MODEL" -t "$(cat prompt.md)" -y -l 0 --exit-immediately --agent-class default \
  -c "$CFG" \
  -c "environment.cwd=$W" -c environment.timeout=1800 \
  -o "$ASI_TRAJ_DIR/$ID.$(date +%s).traj.json" < /dev/null
